Task and canonical criteria:
{
  "taskId": "task_qa078exportreview0001",
  "roomId": "room_qa078exportreview0001",
  "definitionRevision": 1,
  "criteriaRevision": 1,
  "goal": "Review whether this synthetic multi-tenant asynchronous export service is ready for release. Deliver concrete code/security/recovery findings, effective repair and regression plans, preserved correct behavior and unresolved evidence needs. This is read-only review, not implementation or release approval.",
  "criteria": [
    {
      "criterionKey": "criterion_qa078_api",
      "description": "Assess tenant-local idempotency and job/outbox atomicity from the implementation. For any confirmed request-replay defect, give a concrete input, observed consequence and safe correction consistent with the stated API contract.",
      "required": true,
      "ordinal": 1
    },
    {
      "criterionKey": "criterion_qa078_security",
      "description": "Assess creation, worker data scope and download authorization against the security contract, including a previously issued unexpired link after membership revocation. Give an evidence-supported consequence and effective fix for any confirmed gap; preserve valid tenant/signature/expiry controls.",
      "required": true,
      "ordinal": 2
    },
    {
      "criterionKey": "criterion_qa078_recovery",
      "description": "Assess dispatcher crash and both broker failure modes (before delivery and lost acknowledgement after delivery), restart and duplicate delivery. Describe a safe delivery/retry order, remaining ambiguity and deduplication; do not promise exactly-once external execution.",
      "required": true,
      "ordinal": 3
    },
    {
      "criterionKey": "criterion_qa078_concurrency",
      "description": "Assess lease expiry, out-of-order workers and cancellation across database publication AND object-store writes/cleanup. Give a concrete interleaving and safe repair for confirmed races while preserving correct existing database fencing.",
      "required": true,
      "ordinal": 4
    },
    {
      "criterionKey": "criterion_qa078_regressions",
      "description": "Propose concrete preconditions/actions/observable expected results covering: (1) same key with changed payload, (2) same key across tenants and forged body tenant, (3) job/outbox transaction rollback, (4) pre-delivery publish failure plus lost acknowledgement and duplicate delivery, (5) old/new worker publication and cleanup race, (6) cancellation during paused work, (7) unexpired link after membership revocation, (8) normal ready download, expiry and ready-job duplicate. Cases may be combined and equivalent safe behavior is accepted; a checklist of test names alone is insufficient.",
      "required": true,
      "ordinal": 5
    },
    {
      "criterionKey": "criterion_qa078_release",
      "description": "Give a clear release recommendation tied to confirmed blockers and evidence gaps, with a feasible ordered repair/verification plan. Distinguish recommendations from changes actually made; no operational approval or execution is granted by this review.",
      "required": true,
      "ordinal": 6
    },
    {
      "criterionKey": "criterion_qa078_preservation",
      "description": "Explicitly retain the verified-session tenant boundary and tenant-local uniqueness, atomic job/outbox transaction, state/epoch/lease fence for DB publication and the ready/canceled duplicate no-op. Do not claim these existing protections are absent or replace them with weaker controls.",
      "required": true,
      "ordinal": 7
    },
    {
      "criterionKey": "criterion_qa078_uncertainty",
      "description": "Preserve both unprovided evidence groups: real remote-store/IAM/consistency/durability configuration, and production load/lease-latency/recovery-time measurements. State what would resolve each and distinguish observed local scripted checks from production verification and proposed regression tests. Cite relevant source identities throughout; do not invent incidents, test results, causes or approval.",
      "required": true,
      "ordinal": 8
    }
  ],
  "criticalCriterionKeys": [
    "criterion_qa078_api",
    "criterion_qa078_security",
    "criterion_qa078_recovery",
    "criterion_qa078_concurrency",
    "criterion_qa078_regressions",
    "criterion_qa078_release",
    "criterion_qa078_preservation",
    "criterion_qa078_uncertainty"
  ]
}

